<?php require_once __DIR__.'/includes/functions.php';require_role(['admin']);if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$act=$_POST['action']??'';if($act==='role'){$role=$_POST['role']??'user';$status=$_POST['status']??'active';if(!in_array($role,['admin','staff','user'],true)||!in_array($status,['active','disabled'],true))flash('Invalid role/status.','error');elseif($id===current_user()['id']&&($role!=='admin'||$status!=='active'))flash('You cannot disable or demote your own administrator account.','error');else{$s=$db->prepare('UPDATE users SET role=?,status=? WHERE id=?');$s->bind_param('ssi',$role,$status,$id);$s->execute();log_action('user_permissions_updated','users',$id,'role='.$role.', status='.$status);flash('User updated.');}}header('Location: '.url('users.php'));exit;}$q=trim($_GET['q']??'');$s=$db->prepare('SELECT id,name,email,role,is_verified,status,created_at FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY created_at DESC');$like="%$q%";$s->bind_param('ss',$like,$like);$s->execute();$rows=$s->get_result();$title='Manage users';require 'includes/header.php';?><h1>User management</h1><div class="panel"><form method="get"><label>Search name or email</label><input name="q" value="<?=e($q)?>"><button>Search</button></form></div><div class="panel table-wrap"><table><tr><th>User</th><th>Role</th><th>Email verified</th><th>Status</th><th>Update permissions</th></tr><?php while($u=$rows->fetch_assoc()):?><tr><td><?=e($u['name'])?><br><span class="muted"><?=e($u['email'])?></span><br><small>Joined <?=e($u['created_at'])?></small></td><td><?=e($u['role'])?></td><td><?=$u['is_verified']?'Yes':'No'?></td><td><?=e($u['status'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$u['id']?>"><label>Role</label><select name="role"><?php foreach(['admin','staff','user'] as $r):?><option value="<?=$r?>" <?=$u['role']===$r?'selected':''?>><?=$r?></option><?php endforeach;?></select><label>Status</label><select name="status"><option value="active" <?=$u['status']==='active'?'selected':''?>>Active</option><option value="disabled" <?=$u['status']==='disabled'?'selected':''?>>Disabled</option></select><button>Save</button></form></td></tr><?php endwhile;?></table></div><?php require 'includes/footer.php';?>
